    subject = (subject or "").strip()
    if not subject:
        raise ValueError("ticket subject must not be blank")
    cur = conn.execute(
        "INSERT INTO tickets (user_id, subject) VALUES (?, ?)", (user_id, subject)
    )
    conn.commit()
    return cur.lastrowid


def close(conn, ticket_id):
    cur = conn.execute(
        "UPDATE tickets SET status = '"'"'closed'"'"' WHERE id = ?", (ticket_id,)
    )
    if cur.rowcount == 0:
        conn.rollback()
        raise KeyError(ticket_id)
    conn.commit()
